package com.smritisathi.app.games;
import android.os.*;import android.graphics.Color;import android.view.*;import android.widget.*;import java.util.*;import com.smritisathi.app.core.*;
public class ObjectRecallActivity extends GameBase {String[] targets={"🔑 Key","👓 Glasses","⌚ Watch","☕ Cup","📖 Book"};String[] all={"🔑 Key","👓 Glasses","⌚ Watch","☕ Cup","📖 Book","📱 Phone","👟 Shoe","🍎 Apple","🖊 Pen"};ArrayList<String> selected=new ArrayList<>();TextView info;LinearLayout content;long recallStart;@Override public void onCreate(Bundle b){super.onCreate(b);gameHeader("Object Recall","Remember these items carefully...");info=UI.text(this,"Look closely... You have 5 seconds.");root.addView(info);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);root.addView(content);for(String s:targets){Button x=UI.button(this,s);content.addView(x);}new Handler().postDelayed(this::showRecall,5000);}void showRecall(){content.removeAllViews();info.setText("Tap all the items you saw earlier");ArrayList<String> list=new ArrayList<>(Arrays.asList(all));Collections.shuffle(list);for(String s:list){Button x=UI.button(this,s);content.addView(x);x.setOnClickListener(v->{if(selected.contains(s)){selected.remove(s);x.setSelected(false);}else{selected.add(s);x.setSelected(true);}});}Button submit=UI.button(this,"Submit Recall");content.addView(submit);recallStart=System.currentTimeMillis();submit.setOnClickListener(v->finishGame());}void finishGame(){long rt=System.currentTimeMillis()-recallStart;int correct=0,falsePos=0;for(String s:selected)if(Arrays.asList(targets).contains(s))correct++;else falsePos++;int acc=Math.max(0,Math.min(100,Math.round(((correct-falsePos)/5f)*100)));int dur=(int)Math.round(rt/1000.0);int score=Math.round((float)(acc*.8+Math.max(0,100-dur*.4)*.2));complete("objectRecall",score,acc,rt,dur);}}
